<template>
  <section class="equalizer-admin">
    <header class="module-header"><div><span class="admin-eyebrow">ADICIONAL POR CONTA</span><h2>Códigos do equalizador</h2><p>Libere os ajustes da mesa sem alterar a assinatura de músicas.</p></div><span class="admin-status"><i aria-hidden="true" class="mdi mdi-shield-check-outline"/> Validação no Firebase</span></header>
    <p class="admin-info">Padrão: um código vitalício para uma conta. Para campanhas, escolha ativações limitadas ou ilimitadas. Desativar o código bloqueia novos usos; revogar uma conta interrompe o processamento nela.</p>
    <p v-if="error" class="admin-error" role="alert">{{ error }}</p><p v-if="message" class="admin-success" role="status">{{ message }}</p>
    <form class="admin-form" @submit.prevent="create"><label>Quantidade de contas<select v-model="unlimited"><option :value="false">Limitada</option><option :value="true">Ilimitada</option></select></label><label v-if="!unlimited">Máximo de ativações<input v-model.number="maximum" type="number" min="1" max="1000000" required/></label><label>Validade<select v-model="lifetime"><option :value="true">Vitalício</option><option :value="false">Por dias</option></select></label><label v-if="!lifetime">Dias de equalizador<input v-model.number="days" type="number" min="1" max="36500" required/></label><label class="wide">Código manual (opcional)<input v-model="manual" maxlength="120" placeholder="Vazio para gerar EQ + código aleatório" autocomplete="off"/></label><button class="admin-button primary" :disabled="busy">{{ busy?'Aguarde…':'Gerar código do equalizador' }}</button></form>
    <div class="admin-toolbar"><button class="admin-button" @click="load(true)" :disabled="busy"><i aria-hidden="true" class="mdi mdi-refresh"/> Atualizar códigos</button><span class="admin-info">Cada conta usa cada código uma vez. Um novo código por dias amplia a validade restante.</span></div>
    <article v-for="key in keys" :key="key.id" class="eq-key"><div><code>{{ key.code }}</code><p>{{ key.activationCount }} / {{ key.maxActivations===null?'ilimitadas':key.maxActivations }} ativações · {{ key.lifetime?'Vitalício':key.durationDays+' dias' }}</p><span class="admin-status" :class="{muted:!key.active}">{{ key.active?'Código ativo':'Novas ativações bloqueadas' }}</span></div><div class="eq-key-actions"><button class="admin-button" @click="copy(key.code)">Copiar</button><button class="admin-button" @click="showUses(key)">Ver ativações</button><button class="admin-button" @click="toggleKey(key)" :disabled="busy">{{ key.active?'Desativar código':'Reativar código' }}</button></div></article>
    <button v-if="more" class="admin-button" @click="load(false)" :disabled="busy">Carregar mais códigos</button><p v-if="!busy&&!keys.length" class="admin-info">Nenhum código criado. Use o formulário acima para gerar o primeiro.</p>
    <section class="eq-account"><h3>Consultar ou revogar o adicional de uma conta</h3><div class="admin-toolbar"><label>UID da conta<input v-model="lookup" placeholder="UID encontrado em Usuários" @keyup.enter="inspectAccount"/></label><button class="admin-button" @click="inspectAccount" :disabled="busy||!lookup.trim()">Consultar equalizador</button></div><div v-if="account" class="eq-account-result"><strong>{{ account.name }}</strong><p>{{ account.uid }}</p><template v-if="account.grant"><p>{{ account.grant.active?'Liberado':'Revogado' }} · {{ account.grant.lifetime?'Vitalício':formatDate(account.grant.endAt) }}</p><button class="admin-button" @click="toggleGrant" :disabled="busy">{{ account.grant.active?'Revogar equalizador desta conta':'Reativar equalizador desta conta' }}</button><small>A reativação conserva o vencimento original.</small></template><p v-else>Esta conta ainda não possui o adicional do equalizador.</p></div></section>
    <v-dialog v-model="usesOpen" max-width="700" :z-index="15000" aria-labelledby="eq-uses-title"><section class="eq-uses-dialog"><header class="module-header"><div><span class="admin-eyebrow">ATIVAÇÕES REAIS</span><h2 id="eq-uses-title">{{ selectedKey?.code }}</h2></div><button class="admin-button" @click="usesOpen=false" aria-label="Fechar ativações do equalizador"><i aria-hidden="true" class="mdi mdi-close"/></button></header><p v-if="usesError" class="admin-error" role="alert">{{ usesError }}</p><p v-if="usesLoading" role="status">Carregando ativações…</p><article v-for="receipt in uses" :key="receipt.id"><div><code>{{ receipt.uid }}</code><p>{{ formatDate(receipt.createdAt) }} · {{ receipt.lifetime?'Vitalício':formatDate(receipt.endAt) }}</p></div><button class="admin-button" @click="lookup=receipt.uid;usesOpen=false;inspectAccount()">Consultar conta</button></article><p v-if="!usesLoading&&!uses.length">Este código ainda não foi usado.</p><button v-if="usesMore" class="admin-button" @click="loadUses(false)" :disabled="usesLoading">Mais ativações</button></section></v-dialog>
  </section>
</template>
<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue'
import { db } from '@/firebase'
import { collection,doc,getDoc,getDocs,query,where,orderBy,limit,startAfter } from 'firebase/firestore'
import { createEqualizerKey,listEqualizerKeys,setEqualizerKeyActive,setEqualizerGrantActive } from '@/services/equalizer-keys'
import { dateMillis } from '@/utils/access-policy.mjs'
const keys=ref([]),unlimited=ref(false),maximum=ref(1),lifetime=ref(true),days=ref(30),manual=ref(''),error=ref(''),message=ref(''),busy=ref(false),more=ref(false),lookup=ref(''),account=ref(null),usesOpen=ref(false),selectedKey=ref(null),uses=ref([]),usesMore=ref(false),usesLoading=ref(false),usesError=ref('')
let cursor,usesCursor,generation=0,accountRun=0
function formatDate(value){const time=dateMillis(value);return time?new Date(time).toLocaleString('pt-BR'):'—'}
async function load(reset=true){busy.value=true;error.value='';try{const data=await listEqualizerKeys(reset?null:cursor);keys.value=reset?data.keys:[...keys.value,...data.keys];cursor=data.cursor;more.value=data.more}catch(e){error.value=e.code==='permission-denied'?'Publique as regras atualizadas do projeto para gerenciar os códigos do equalizador.':e.message}finally{busy.value=false}}
async function create(){busy.value=true;error.value='';message.value='';try{const code=await createEqualizerKey(manual.value||'EQ-'+crypto.randomUUID().replace(/-/g,'').toUpperCase(),{maxActivations:unlimited.value?null:maximum.value,lifetime:lifetime.value,durationDays:days.value});manual.value='';message.value='Código criado: '+code;await load(true)}catch(e){error.value=e.message}finally{busy.value=false}}
async function toggleKey(key){busy.value=true;error.value='';try{await setEqualizerKeyActive(key.id,!key.active);key.active=!key.active;message.value=key.active?'Código reativado.':'Novas ativações bloqueadas. As contas já liberadas conservam o adicional.'}catch(e){error.value=e.message}finally{busy.value=false}}
async function copy(code){try{await navigator.clipboard.writeText(code);message.value='Código copiado.'}catch{message.value='Selecione e copie o código exibido.'}}
async function inspectAccount(){const uid=lookup.value.trim();if(!uid||uid.includes('/'))return;const run=++accountRun;account.value=null;error.value='';busy.value=true;try{const [p,g]=await Promise.all([getDoc(doc(db,'users',uid)),getDoc(doc(db,'users',uid,'addons','equalizer'))]);if(run!==accountRun)return;if(!p.exists())throw new Error('Conta não encontrada.');const data=p.data();account.value={uid,name:`${data.firstName||''} ${data.lastName||''}`.trim()||data.email||uid,grant:g.exists()?g.data():null}}catch(e){if(run===accountRun)error.value=e.message}finally{if(run===accountRun)busy.value=false}}
async function toggleGrant(){const current=account.value;if(!current?.grant)return;const active=!current.grant.active;if(!window.confirm(active?'Reativar o equalizador desta conta, conservando o vencimento?':'Revogar o equalizador desta conta? A assinatura e o player continuam funcionando.'))return;busy.value=true;error.value='';try{await setEqualizerGrantActive(current.uid,active);current.grant.active=active;message.value=active?'Adicional reativado.':'Adicional revogado. A mudança será aplicada quando o aparelho receber a atualização.'}catch(e){error.value=e.message}finally{busy.value=false}}
async function showUses(key){selectedKey.value=key;uses.value=[];usesCursor=null;usesOpen.value=true;await loadUses(true)}
async function loadUses(reset){const run=++generation,id=selectedKey.value?.id;usesLoading.value=true;usesError.value='';try{const terms=[where('keyId','==',id),orderBy('createdAt','desc')];if(!reset&&usesCursor)terms.push(startAfter(usesCursor));const snap=await getDocs(query(collection(db,'equalizerRedemptions'),...terms,limit(26)));if(run!==generation)return;const rows=snap.docs.slice(0,25).map(d=>({id:d.id,...d.data()}));uses.value=reset?rows:[...uses.value,...rows];usesCursor=snap.docs.slice(0,25).at(-1);usesMore.value=snap.size>25}catch(e){if(run===generation)usesError.value=e.code==='failed-precondition'?'Publique os índices de firestore.indexes.json e aguarde sua criação.':e.message}finally{if(run===generation)usesLoading.value=false}}
onMounted(()=>load(true));onBeforeUnmount(()=>{generation++;accountRun++})
</script>
<style scoped>
.eq-key{display:flex;gap:16px;align-items:center;border:1px solid #35543f;border-radius:14px;padding:18px;margin-bottom:12px;background:#18281e}.eq-key>div:first-child{flex:1;min-width:0}.eq-key code{color:#d4f0df;font-size:15px;overflow-wrap:anywhere}.eq-key p{font-size:12px;color:#a9c3b1;margin:8px 0}.eq-key-actions{display:flex;flex-wrap:wrap;gap:7px}.eq-account{margin-top:30px;padding:24px;border:1px solid #3c5b46;border-radius:18px}.eq-account h3{font-size:20px}.eq-account-result{padding:18px;background:#20372a;border-radius:12px;overflow-wrap:anywhere}.eq-account-result p{font-size:12px;color:#b4cdbe;margin:9px 0}.eq-account-result small{display:block;margin-top:10px;color:#a8c4b3;font-size:11px}.eq-uses-dialog{padding:25px;background:#132219;color:#edf8f1;border:1px solid #40664c;border-radius:20px;max-height:85dvh;overflow:auto}.eq-uses-dialog h2{overflow-wrap:anywhere}.eq-uses-dialog article{display:flex;align-items:center;gap:14px;padding:18px 0;border-bottom:1px solid #385340}.eq-uses-dialog article>div{flex:1;min-width:0}.eq-uses-dialog code{overflow-wrap:anywhere;font-size:12px}.eq-uses-dialog p{font-size:12px;color:#adc6b7;margin:9px 0}@media(max-width:700px){.eq-key{align-items:stretch;flex-direction:column}.eq-key-actions .admin-button{flex:1;font-size:11px;padding:10px}.eq-account{padding:18px}.eq-uses-dialog{padding:18px}.eq-uses-dialog article{flex-direction:column;align-items:stretch}}
</style>
